-- « Rédaction en masse » (LecteurRedactionEnMasse, EcrivainRedactionEnMasse), lot 10 du plan « RIG v3 100 % fonctionnel » (plan-676a4b19).
-- Identifiants 2 000 8xx, roles 2026RM208xx (instances CX sans code affaire), audience du 18/07/1990 : hors des fenetres des autres ecrans
-- d'audience ; la recherche par sa date la choisit (PROC_REDA_MASSE.recherches). Ce qui est retenu ou ecarte : PROC_REDA_MASSE.attendu.
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_CAT_DECISION') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_CAT_DECISION varchar(1) NULL;
IF COL_LENGTH('v2.DECISION_JUDICIAIRE', 'DCJDC_ID_APPAF_DELIBERER') IS NULL ALTER TABLE v2.DECISION_JUDICIAIRE ADD DCJDC_ID_APPAF_DELIBERER int NULL;
IF COL_LENGTH('v2.TYPE_DECISION', 'R_TYPEDECISI_DECISION_AVEC_REDACTION') IS NULL ALTER TABLE v2.TYPE_DECISION ADD R_TYPEDECISI_DECISION_AVEC_REDACTION bit NULL;
IF COL_LENGTH('v2.APPEL_AFFAIRE', 'APPAF_TYPE_CLASSEMENT') IS NULL ALTER TABLE v2.APPEL_AFFAIRE ADD APPAF_TYPE_CLASSEMENT varchar(5) NULL;
IF OBJECT_ID(N'v2.TYPE_CLASSEMENT') IS NULL
    CREATE TABLE v2.TYPE_CLASSEMENT (R_TYPECLASSE_VALEUR varchar(5) NOT NULL PRIMARY KEY, R_TYPECLASSE_LIBELLE_ECRAN varchar(35) NOT NULL,
        R_TYPECLASSE_PRONONCE bit NOT NULL DEFAULT (0));
IF OBJECT_ID(N'v2.ETAT_REDACTION') IS NULL
    CREATE TABLE v2.ETAT_REDACTION (R_ETATREDACT_VALEUR varchar(1) NOT NULL PRIMARY KEY, R_ETATREDACT_LIBELLE_ECRAN varchar(100) NOT NULL);

-- Les etats de redaction (ETAT_REDACTION de RIG_DEV), un type a minute (JGRMX, un compteur par jour), un type sans serie, un type « avec
-- redaction » pour la decision sans prononce.
EXEC sp_executesql N'
INSERT INTO v2.ETAT_REDACTION (R_ETATREDACT_VALEUR, R_ETATREDACT_LIBELLE_ECRAN)
SELECT v, l FROM (VALUES (''0'', ''à créer''), (''1'', ''brouillon''), (''2'', ''projet en révision''), (''3'', ''projet révisé à rendre''),
    (''4'', ''jugement rendu avant signature''), (''5'', ''jugement rendu et signé'')) AS x (v, l)
WHERE NOT EXISTS (SELECT 1 FROM v2.ETAT_REDACTION AS e WHERE e.R_ETATREDACT_VALEUR = x.v);
INSERT INTO v2.TYPE_DECISION (R_TYPEDECISI_VALEUR, R_TYPEDECISI_LIBELLE_ECRAN, R_TYPEDECISI_NUM_REPERTOIRE, R_TYPEDECISI_DECISION_AVEC_REDACTION) VALUES
    (''RMJUG20'', ''Jugement rédigé du banc'', ''JGRMX'', 0), (''RMSANS20'', ''Jugement sans série du banc'', NULL, 0),
    (''RMAVEC20'', ''Ordonnance avec rédaction du banc'', ''JGRMX'', 1);
INSERT INTO num.Compteur (Type, Annee, Jour, Structure, CodageAnnee, TailleChrono, Debut) VALUES (''JGRMX'', 1990, 1, ''AQC'', 2, 5, 1);';

-- L'audience 2000801 (18/07/1990, quantieme 199), appels 1 a 8 ; l'appel 9 (instance 2000801) porte le delibere. 2000801 brouillon
-- (validable), 2000802 en revision SANS document REDA (refus : modele), 2000803 a creer (refus : generation), 2000804 minute validee (etat
-- 3), 2000805 et 2000806 prononcees au MEME appel (ecartees : « 1 seul prononcé »), 2000807 ordonnance de l'instance de l'appel 6, sans
-- prononce, type « avec rédaction » (retenue), 2000808 en revision sans delibere (refus), 2000809 brouillon d'un type sans serie (refus).
EXEC sp_executesql N'
INSERT INTO v2.AUDIENCE_CABINET (AUDNC_ID_ADNC, AUDNC_DATE, AUDNC_HEURE, AUDNC_AUDIENCE) VALUES (2000801, ''1990-07-18'', ''09:30'', 1);
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_TYPE_INSTANCE)
SELECT n, ''2026RM2'' + RIGHT(CONVERT(varchar(7), n), 4), ''REDA '' + CHAR(64 + n - 2000800), ''CX'' FROM (VALUES (2000801), (2000802), (2000803), (2000804),
    (2000805), (2000806), (2000808), (2000809)) AS x (n);
INSERT INTO v2.APPEL_AFFAIRE (APPAF_ID_APPAF, APPAF_ID_INSTN, APPAF_NUM_ORDRE, APPAF_ID_ADNC, APPAF_NUM_APPEL) VALUES
    (2000801, 2000801, 1, 2000801, ''1''), (2000802, 2000802, 2, 2000801, ''2''), (2000803, 2000803, 3, 2000801, ''3''), (2000804, 2000804, 4, 2000801, ''4''),
    (2000805, 2000805, 5, 2000801, ''5''), (2000806, 2000806, 6, 2000801, ''6''), (2000808, 2000808, 7, 2000801, ''7''), (2000809, 2000809, 8, 2000801, ''8''),
    (2000810, 2000801, 9, 2000801, ''9'');
INSERT INTO v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC, DCJDC_ID_INSTN, DCJDC_NUM_ORDRE, DCJDC_DATE_PREVUE, DCJDC_DATE, DCJDC_TYPE_DECISION, DCJDC_ETAT_REDACTION,
                                    DCJDC_CAT_DECISION, DCJDC_NUM_REPERTOIRE, DCJDC_ID_APPAF_PRONONCER, DCJDC_ID_APPAF_DELIBERER) VALUES
    (2000801, 2000801, 1, ''1990-07-01'', NULL, ''RMJUG20'', ''1'', ''J'', NULL, 2000801, 2000810),
    (2000802, 2000802, 1, ''1990-07-01'', NULL, ''RMJUG20'', ''2'', ''J'', NULL, 2000802, 2000810),
    (2000803, 2000803, 1, ''1990-07-01'', NULL, ''RMJUG20'', ''0'', ''J'', NULL, 2000803, 2000810),
    (2000804, 2000804, 1, ''1990-07-18'', ''1990-07-18'', ''RMJUG20'', ''3'', ''J'', ''9019900001'', 2000804, 2000810),
    (2000805, 2000805, 1, ''1990-07-01'', NULL, ''RMJUG20'', ''1'', ''J'', NULL, 2000805, 2000810),
    (2000806, 2000805, 2, ''1990-07-01'', NULL, ''RMJUG20'', ''1'', ''J'', NULL, 2000805, 2000810),
    (2000807, 2000806, 1, ''1990-07-01'', NULL, ''RMAVEC20'', ''1'', ''O'', NULL, NULL, 2000810),
    (2000808, 2000808, 1, ''1990-07-01'', NULL, ''RMJUG20'', ''2'', ''J'', NULL, 2000808, NULL),
    (2000809, 2000809, 1, ''1990-07-01'', NULL, ''RMSANS20'', ''1'', ''J'', NULL, 2000809, 2000810);
INSERT INTO v2.DOCUMENT_DOSSIER (DCMDS_ID_DCMDS, DCMDS_CODE_ENTITE, DCMDS_VALEUR_ID_METIER, DCMDS_CODE_MODELE_DOCUMENT)
SELECT n, ''REDA_DECI_JUD'', n, ''MODRM20'' FROM (VALUES (2000801), (2000803), (2000804), (2000807), (2000808), (2000809)) AS x (n);';

-- La liste sans recherche (la fenetre du retour d'audience, J-10 a J : INTERV_AUD_DATE_MIN_RETAUD = 10, PROC_RETAUD.sql) : l'audience
-- 2000802, neuf jours avant le jour du banc, et sa decision 2000810 (brouillon, avec son document REDA : hors de « Signature
-- électronique »). L'appel n'a pas de type de classement : le retour d'audience ne le lit pas.
EXEC sp_executesql N'
INSERT INTO v2.AUDIENCE_CABINET (AUDNC_ID_ADNC, AUDNC_DATE, AUDNC_HEURE, AUDNC_AUDIENCE) VALUES (2000802, DATEADD(day, -9, @aujourdhui), ''09:30'', 1);
INSERT INTO v2.INSTANCE (INSTN_ID_INSTN, INSTN_NUM_ROLE, INSTN_NOM_COURANT, INSTN_TYPE_INSTANCE) VALUES (2000810, ''2026RM20810'', ''REDA J'', ''CX'');
INSERT INTO v2.APPEL_AFFAIRE (APPAF_ID_APPAF, APPAF_ID_INSTN, APPAF_NUM_ORDRE, APPAF_ID_ADNC, APPAF_NUM_APPEL) VALUES (2000811, 2000810, 1, 2000802, ''1'');
INSERT INTO v2.DECISION_JUDICIAIRE (DCJDC_ID_DCJDC, DCJDC_ID_INSTN, DCJDC_NUM_ORDRE, DCJDC_DATE_PREVUE, DCJDC_DATE, DCJDC_TYPE_DECISION, DCJDC_ETAT_REDACTION,
                                    DCJDC_CAT_DECISION, DCJDC_NUM_REPERTOIRE, DCJDC_ID_APPAF_PRONONCER, DCJDC_ID_APPAF_DELIBERER)
VALUES (2000810, 2000810, 1, DATEADD(day, -9, @aujourdhui), NULL, ''RMJUG20'', ''1'', ''J'', NULL, 2000811, 2000811);
INSERT INTO v2.DOCUMENT_DOSSIER (DCMDS_ID_DCMDS, DCMDS_CODE_ENTITE, DCMDS_VALEUR_ID_METIER, DCMDS_CODE_MODELE_DOCUMENT) VALUES (2000810, ''REDA_DECI_JUD'', 2000810, ''MODRM20'');',
N'@aujourdhui datetime', @aujourdhui;
